"""Self-contained binary document transactions, shared by direct and SSH clients.

The source is included in the existing framed SSH helper; it has no external
dependencies. Payloads are bounded and commit uses an original-content digest.
"""
DOCUMENT_HELPER = "\nimport base64, contextlib, hashlib, json, os, pathlib, re, stat, sys, tempfile, time, uuid\n\ndef document_store():\n    if os.name == 'nt':\n        root = pathlib.Path(os.environ['LOCALAPPDATA']) / 'CodexRelayClient' / 'document-transfers'\n    elif sys.platform == 'darwin':\n        root = pathlib.Path.home() / 'Library/Application Support/CodexRelayClient/document-transfers'\n    else:\n        root = pathlib.Path.home() / '.local/state/coderelaybridge-document-transfers'\n    root.mkdir(parents=True, exist_ok=True, mode=0o700)\n    if root.is_symlink() or not root.is_dir():\n        raise ValueError('文档暂存目录身份无效')\n    if os.name != 'nt' and (root.stat().st_uid != os.getuid() or root.stat().st_mode & 0o077):\n        raise ValueError('文档暂存目录权限无效')\n    return root\n\ndef document_target(raw):\n    if not isinstance(raw, str) or not raw or len(raw) > 4096 or '\\x00' in raw:\n        raise ValueError('文档路径无效')\n    source = pathlib.Path(raw).expanduser()\n    if source.is_symlink() or getattr(source, 'is_junction', lambda: False)():\n        raise ValueError('请打开文档的实际路径，不直接编辑链接')\n    target = source.resolve(strict=True)\n    if not target.is_file():\n        raise ValueError('不是普通文档文件')\n    return target\n\ndef document_digest(path):\n    digest = hashlib.sha256()\n    with path.open('rb') as stream:\n        info = os.fstat(stream.fileno())\n        if not stat.S_ISREG(info.st_mode) or info.st_size > 32 * 1024 * 1024:\n            raise ValueError('文档编辑上限为 32 MB')\n        for block in iter(lambda: stream.read(1024 * 1024), b''):\n            digest.update(block)\n        after = os.fstat(stream.fileno())\n    if (info.st_size, info.st_mtime_ns, info.st_ctime_ns) != (after.st_size, after.st_mtime_ns, after.st_ctime_ns):\n        raise ValueError('读取期间文档已变化，请重新打开')\n    return digest.hexdigest(), info\n\ndef document_atomic_json(path, value):\n    fd, name = tempfile.mkstemp(prefix='.receipt-', dir=path.parent)\n    try:\n        with os.fdopen(fd, 'w', encoding='utf-8') as stream:\n            json.dump(value, stream, ensure_ascii=False); stream.flush(); os.fsync(stream.fileno())\n        os.replace(name, path)\n    finally:\n        if os.path.exists(name): os.unlink(name)\n\n@contextlib.contextmanager\ndef document_lock(path):\n    flags = os.O_RDWR | os.O_CREAT | getattr(os, 'O_NOFOLLOW', 0)\n    fd = os.open(path, flags, 0o600)\n    stream = os.fdopen(fd, 'r+b', buffering=0)\n    locked = False\n    try:\n        if path.is_symlink() or not stat.S_ISREG(os.fstat(fd).st_mode):\n            raise ValueError('文档事务锁身份无效')\n        if os.fstat(fd).st_size == 0: stream.write(b'0')\n        deadline = time.monotonic() + 10\n        while True:\n            try:\n                if os.name == 'nt':\n                    import msvcrt\n                    stream.seek(0); msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)\n                else:\n                    import fcntl\n                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)\n                locked = True; break\n            except OSError:\n                if time.monotonic() >= deadline: raise ValueError('文档正在保存，请稍后重试')\n                time.sleep(.05)\n        yield\n    finally:\n        if locked:\n            if os.name == 'nt':\n                import msvcrt\n                stream.seek(0); msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)\n            else:\n                import fcntl\n                fcntl.flock(fd, fcntl.LOCK_UN)\n        stream.close()\n\ndef document_operation(req):\n    action = req['action']\n    if action == 'document_probe':\n        path = document_target(req.get('path'))\n        digest, info = document_digest(path)\n        return dict(ok=True, path=str(path), name=path.name, size=info.st_size, sha256=digest,\n                    modified=info.st_mtime_ns, writable=os.access(path, os.W_OK) and os.access(path.parent, os.W_OK))\n    transaction = str(req.get('transaction') or '')\n    if not re.fullmatch(r'[0-9a-f]{32}', transaction): raise ValueError('文档事务标识无效')\n    root = document_store(); metadata = root / (transaction + '.json'); lock = root / '.transactions.lock'\n    forget = False\n    with document_lock(lock):\n        if action == 'document_begin':\n            # The shared lock is durable coordination, not a per-transfer cache.\n            # Stale partial payloads are disposable; the server retains the full\n            # edited recovery copy. Unknown commit receipts remain for seven days.\n            for receipt in root.glob('*.json'):\n                if not re.fullmatch(r'[0-9a-f]{32}\\.json', receipt.name) or receipt.is_symlink(): continue\n                if time.time() - receipt.stat().st_mtime < 7 * 86400: continue\n                old = json.loads(receipt.read_text(encoding='utf-8'))\n                if old.get('schema') != 1 or old.get('transaction') != receipt.stem: continue\n                staged = pathlib.Path(old['path']).parent / ('.crb-office-' + receipt.stem + '.part')\n                if not staged.is_symlink() and staged.is_file(): staged.unlink()\n                receipt.unlink()\n        if metadata.is_symlink(): raise ValueError('文档事务身份无效')\n        record = json.loads(metadata.read_text(encoding='utf-8')) if metadata.exists() else None\n        if record and record.get('schema') == 1 and record.get('transaction') == transaction and record.get('state') == 'ready':\n            destination = pathlib.Path(record['path'])\n            backup = destination.parent / ('.crb-office-' + transaction + '.original')\n            if not destination.exists() and backup.is_file() and not backup.is_symlink():\n                old, _ = document_digest(backup)\n                if old == record['expected']:os.replace(backup, destination)\n        if action == 'document_begin':\n            path = document_target(req.get('path')); expected = str(req.get('expectedSha256') or ''); size = req.get('size')\n            if not re.fullmatch(r'[0-9a-f]{64}', expected) or type(size) is not int or not 0 < size <= 32 * 1024 * 1024:\n                raise ValueError('文档保存参数无效')\n            if record:\n                if record['path'] != str(path) or record['expected'] != expected or record['size'] != size:\n                    raise ValueError('文档事务参数冲突')\n            else:\n                actual, info = document_digest(path)\n                if actual != expected: raise ValueError('原文档已被其他程序修改；未覆盖，请下载编辑副本')\n                part = path.parent / ('.crb-office-' + transaction + '.part')\n                fd = os.open(part, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_NOFOLLOW', 0), 0o600)\n                os.close(fd)\n                record = dict(schema=1, transaction=transaction, path=str(path), expected=expected, size=size,\n                              received=0, state='receiving', updated=time.time(), mode=stat.S_IMODE(info.st_mode))\n                try: document_atomic_json(metadata, record)\n                except BaseException:\n                    part.unlink(); raise\n        if not record or record.get('schema') != 1 or record.get('transaction') != transaction:\n            raise ValueError('文档保存事务不存在，请重新保存')\n        path = pathlib.Path(record['path']); part = path.parent / ('.crb-office-' + transaction + '.part')\n        if action == 'document_chunk':\n            data = base64.b64decode(req.get('data', ''), validate=True); offset = req.get('offset')\n            if type(offset) is not int or not data or len(data) > 128 * 1024 or offset < 0 or offset + len(data) > record['size']:\n                raise ValueError('文档分块参数无效')\n            if record['state'] != 'receiving': raise ValueError('文档事务不接受新的分块')\n            if part.is_symlink() or not part.is_file(): raise ValueError('文档暂存文件身份无效')\n            with part.open('r+b') as stream:\n                if offset < record['received']:\n                    stream.seek(offset)\n                    if offset + len(data) > record['received'] or stream.read(len(data)) != data:\n                        raise ValueError('文档重试分块内容不一致')\n                elif offset == record['received']:\n                    stream.seek(offset); stream.write(data); stream.flush(); os.fsync(stream.fileno())\n                    record['received'] += len(data)\n                else: raise ValueError('文档分块不连续')\n        elif action == 'document_commit':\n            digest = str(req.get('sha256') or '')\n            if not re.fullmatch(r'[0-9a-f]{64}', digest): raise ValueError('文档校验值无效')\n            if record['state'] == 'committed':\n                if record.get('sha256') != digest: raise ValueError('已保存事务的校验值冲突')\n            else:\n                if record['state'] not in ('receiving', 'ready') or record['received'] != record['size']:\n                    raise ValueError('文档尚未完整传输')\n                current = document_target(str(path)); actual, info = document_digest(current)\n                if current != path:raise ValueError('原文档路径已变化，未覆盖')\n                if record['state'] == 'ready' and not part.exists() and actual == digest and record.get('sha256') == digest:\n                    record['state'] = 'committed'\n                else:\n                    if actual != record['expected']: raise ValueError('原文档已被其他程序修改；未覆盖，请下载编辑副本')\n                    if part.is_symlink() or not part.is_file(): raise ValueError('文档暂存文件身份无效')\n                    transferred, staged = document_digest(part)\n                    if transferred != digest or staged.st_size != record['size']: raise ValueError('文档传输校验失败')\n                    record.update(state='ready', sha256=digest); document_atomic_json(metadata, record)\n                    os.chmod(part, record['mode'])\n                    latest, latest_info = document_digest(document_target(str(path)))\n                    if latest != record['expected']: raise ValueError('原文档已变化，未覆盖')\n                    if os.name == 'nt':\n                        # ReplaceFile preserves the destination's DACL and\n                        # native metadata; a sharing/permission failure leaves\n                        # the original in place and retains the recovery copy.\n                        import ctypes\n                        from ctypes import wintypes\n                        replace = ctypes.WinDLL('kernel32', use_last_error=True).ReplaceFileW\n                        replace.argtypes = [wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.LPCWSTR,\n                                            wintypes.DWORD, wintypes.LPVOID, wintypes.LPVOID]\n                        replace.restype = wintypes.BOOL\n                        backup = path.parent / ('.crb-office-' + transaction + '.original')\n                        if backup.exists():raise ValueError('文档回滚副本尚待核对，请先重试保存')\n                        if not replace(str(path), str(part), str(backup), 0, None, None):\n                            failure = ctypes.get_last_error()\n                            # ReplaceFile may rename the original before an\n                            # error. Restore only our byte-verified backup to\n                            # an absent destination; never replace a new file.\n                            if not path.exists() and backup.is_file() and not backup.is_symlink():\n                                restored, _ = document_digest(backup)\n                                if restored == record['expected']:os.replace(backup, path)\n                            if backup.is_file() and path.is_file():\n                                old, _ = document_digest(backup); current, _ = document_digest(path)\n                                if old == record['expected'] and current == record['expected']:backup.unlink()\n                            raise ctypes.WinError(failure)\n                    else:\n                        staged_info = part.stat()\n                        if (staged_info.st_uid, staged_info.st_gid) != (latest_info.st_uid, latest_info.st_gid):\n                            os.chown(part, latest_info.st_uid, latest_info.st_gid)\n                        if hasattr(os, 'listxattr'):\n                            for attribute in os.listxattr(path):\n                                os.setxattr(part, attribute, os.getxattr(path, attribute))\n                        os.replace(part, path)\n                    record['state'] = 'committed'\n        elif action == 'document_abort':\n            if record['state'] != 'committed':\n                if part.is_symlink(): raise ValueError('文档暂存文件身份无效')\n                if part.exists(): part.unlink()\n                record['state'] = 'aborted'\n        elif action == 'document_forget':\n            if record['state'] not in ('committed', 'aborted'): raise ValueError('不能清除未完成文档事务')\n            forget = True\n        elif action not in ('document_begin', 'document_status'):\n            raise ValueError('不支持的文档操作')\n        record['updated'] = time.time()\n        if forget: metadata.unlink()\n        else: document_atomic_json(metadata, record)\n        if record['state'] == 'committed':\n            backup = path.parent / ('.crb-office-' + transaction + '.original')\n            if backup.is_file() and not backup.is_symlink():\n                old, _ = document_digest(backup)\n                if old == record['expected']:backup.unlink()\n        result = dict(ok=True, transaction=transaction, state=record['state'], received=record['received'],\n                      size=record['size'], sha256=record.get('sha256'), forgotten=forget)\n    return result\n"
